import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

function HomePage() {
  const [availableSlots, setAvailableSlots] = useState(1000);
  const navigate = useNavigate();

  const handleBookNow = () => {
    if (availableSlots > 0) {
      navigate("/booking");
    } else {
      alert("No slots available!");
    }
  };

  return (
    <div style={styles.container}>
      <h1>Parking Slot Dashboard</h1>
      <h2>Available Slots: {availableSlots}</h2>
      <button style={styles.button} onClick={handleBookNow}>
        Book Now
      </button>
    </div>
  );
}

const styles = {
  container: { textAlign: "center", marginTop: "50px" },
  button: { padding: "10px 20px", fontSize: "18px", cursor: "pointer" }
};

export default HomePage;
